<script>
export default {
  name: "PreloaderMain",
  data() {
    return {
      loading: false,
      progress: 0,
      duration: 2000, // 2 seconds
      intervalId: null,
      fadeAway: false,
    };
  },
  methods: {
    start() {
      this.loading = true;
      /*setTimeout(() => {
        this.loading = false;
      }, 2000);*/
    },
    startCounter() {
      const increment = 1;
      const steps = Math.ceil((100 - this.progress) / increment);
      const intervalDuration = this.duration / steps;

      this.intervalId = setInterval(() => {
        if (this.progress >= 100) {
          clearInterval(this.intervalId);
          return;
        }
        this.progress += increment;
      }, intervalDuration);
    }
  },
  mounted() {
    this.startCounter();
  },
  watch: {
    progress(val) {
      if (this.progress === 100) {
        this.fadeAway = true;
        setTimeout(() => {
          this.loading = false;
        }, 1000);
      }
    }
  }
}
</script>

